    for i=1,#Configs do
        for j=1,#Configs[i] do
            table.insert(DoorsConfig,Configs[i][j])
        end
    end
    print("^1[DOORS]^0 - Foram carregadas "..#DoorsConfig.." portas.")
    Wait(100)
    InitWorldGrid()
    RegisterAllConfigDoors()
end)